import { useCallback, useEffect, useRef, useState } from "react";
import { ArrowLeft, ChevronDown, Eye, EyeOff, RefreshCw, AlertCircle, Loader2, CheckCircle2 } from "lucide-react";

/*
  Add to index.html:
  <link href="https://fonts.googleapis.com/css2?family=Playfair+Display:wght@600;700;800&family=Poppins:wght@400;500;600;700&display=swap" rel="stylesheet">

  Usage:
  <TeacherRegistration onSubmit={async ({ userType, userId, password, captcha }) => { ...call your API... }} />

  Fields (same as the Teacher / Academic Staff portal form): User Type, User ID (Email ID), Password,
  Captcha with "Refresh Captcha", and the "Click to Login" / "Click to Reset" buttons.

  IMPORTANT: the captcha below is generated and checked in the browser so the page works on its own.
  For a real login, create the captcha on your server and verify it there (browser-only captchas can be bypassed).
*/

// Campus photo (blurred background) and college crest, embedded as base64
const campusBg =
  "data:image/jpeg;base64,";
const logo =
  "data:image/png;base64,";

// Edit this list to match the user types your portal allows
const USER_TYPES = ["Teacher", "Head of Department (HOD)", "Academic Staff", "Principal"];

/* ───────────── captcha ───────────── */
function newCaptchaText(length = 4) {
  const buf = new Uint32Array(length);
  window.crypto.getRandomValues(buf);
  return Array.from(buf, (n) => n % 10).join("");
}

function drawCaptcha(canvas, text) {
  const dpr = window.devicePixelRatio || 1;
  const w = 300;
  const h = 84;
  canvas.width = w * dpr;
  canvas.height = h * dpr;
  const ctx = canvas.getContext("2d");
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

  ctx.fillStyle = "#f6f3ec";
  ctx.fillRect(0, 0, w, h);

  // speckle noise
  for (let i = 0; i < 380; i++) {
    ctx.fillStyle = `rgba(20,35,75,${0.15 + Math.random() * 0.6})`;
    ctx.fillRect(Math.random() * w, Math.random() * h, 1 + Math.random() * 1.6, 1 + Math.random() * 1.6);
  }
  // a few strike-through lines
  for (let i = 0; i < 3; i++) {
    ctx.strokeStyle = `rgba(143,0,20,${0.25 + Math.random() * 0.25})`;
    ctx.lineWidth = 1.2;
    ctx.beginPath();
    ctx.moveTo(Math.random() * 40, Math.random() * h);
    ctx.bezierCurveTo(w * 0.3, Math.random() * h, w * 0.6, Math.random() * h, w - Math.random() * 40, Math.random() * h);
    ctx.stroke();
  }

  // digits
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  const step = (w - 70) / Math.max(1, text.length - 1);
  [...text].forEach((ch, i) => {
    ctx.save();
    ctx.translate(35 + i * step, h / 2 + (Math.random() - 0.5) * 12);
    ctx.rotate((Math.random() - 0.5) * 0.6);
    ctx.font = `bold ${44 + Math.floor(Math.random() * 8)}px "Courier New", monospace`;
    ctx.fillStyle = "#1f3a6e";
    ctx.fillText(ch, 0, 0);
    ctx.restore();
  });
}

/* ───────────── page ───────────── */
export default function TeacherLogin({ onSubmit })  {
  const [form, setForm] = useState({ userType: "", userId: "", password: "", captcha: "" });
  const [errors, setErrors] = useState({});
  const [showPw, setShowPw] = useState(false);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState(null); // { type: "error" | "info", text }
  const [captchaText, setCaptchaText] = useState("");
  const canvasRef = useRef(null);

  const refreshCaptcha = useCallback(() => {
    setCaptchaText(newCaptchaText());
    setForm((f) => ({ ...f, captcha: "" }));
  }, []);

  useEffect(() => {
    setCaptchaText(newCaptchaText());
  }, []);

  useEffect(() => {
    if (canvasRef.current && captchaText) drawCaptcha(canvasRef.current, captchaText);
  }, [captchaText]);

  const set = (key, value) => {
    setForm((f) => ({ ...f, [key]: value }));
    if (errors[key]) setErrors((e) => ({ ...e, [key]: undefined }));
    if (message) setMessage(null);
  };

  const validate = () => {
    const e = {};
    if (!form.userType) e.userType = "Please select a user type.";
    if (!form.userId.trim()) e.userId = "Enter your User ID (Email ID).";
    else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(form.userId.trim())) e.userId = "Enter a valid email address.";
    if (!form.password) e.password = "Enter your password.";
    if (!form.captcha.trim()) e.captcha = "Enter the captcha shown below.";
    setErrors(e);
    return Object.keys(e).length === 0;
  };

  const handleSubmit = async (ev) => {
    ev.preventDefault();
    setMessage(null);
    if (!validate()) return;

    if (form.captcha.trim() !== captchaText) {
      setErrors({ captcha: "Captcha does not match. Please try again." });
      refreshCaptcha();
      return;
    }

    try {
      setLoading(true);
      if (onSubmit) {
        await onSubmit({ userType: form.userType, userId: form.userId.trim(), password: form.password, captcha: form.captcha.trim() });
      } else {
        await new Promise((r) => setTimeout(r, 900)); // demo only
        setMessage({ type: "info", text: "The form is valid. Connect the onSubmit prop to your login API to sign in." });
      }
    } catch (err) {
      setMessage({ type: "error", text: err?.message || "Login failed. Please check your details and try again." });
      refreshCaptcha();
    } finally {
      setLoading(false);
    }
  };

  const handleReset = () => {
    setForm({ userType: "", userId: "", password: "", captcha: "" });
    setErrors({});
    setMessage(null);
    setShowPw(false);
    setCaptchaText(newCaptchaText());
  };

  const input =
    "h-12 w-full rounded-lg border bg-white px-4 text-sm text-slate-800 placeholder:text-slate-400 transition focus:outline-none focus:ring-4";
  const ok = "border-slate-300 focus:border-[#8f0014] focus:ring-[#8f0014]/10";
  const bad = "border-[#e0473b] focus:border-[#e0473b] focus:ring-[#e0473b]/10";

  const Label = ({ htmlFor, children }) => (
    <label htmlFor={htmlFor} className="mb-1.5 block text-sm font-semibold text-[#14234b]">
      {children} <span className="text-[#e0473b]" aria-hidden="true">*</span>
    </label>
  );
  const Err = ({ id, text }) =>
    text ? (
      <p id={id} className="mt-1.5 flex items-center gap-1 text-xs text-[#c2362b]">
        <AlertCircle size={12} /> {text}
      </p>
    ) : null;

  return (
    <main className="relative isolate flex min-h-screen items-center justify-center overflow-hidden bg-[#14234b] px-4 py-20 font-['Poppins',sans-serif]">
      <style>{`
        @keyframes cardIn { from { opacity: 0; transform: translateY(18px) scale(.985) } to { opacity: 1; transform: none } }
        .card-in { animation: cardIn .6s cubic-bezier(.2,.7,.2,1) both; }
        @media (prefers-reduced-motion: reduce) { .card-in { animation: none; } }
      `}</style>

      {/* blurred campus background */}
      <div className="absolute -inset-6 -z-30 scale-105 bg-cover bg-center blur-[8px]" style={{ backgroundImage: `url(${campusBg})` }} aria-hidden="true" />
      <div className="absolute inset-0 -z-20 bg-gradient-to-br from-[#14234b]/85 via-[#14234b]/65 to-[#8f0014]/50" aria-hidden="true" />

      <a
        href="/"
        className="absolute left-4 top-4 inline-flex items-center gap-2 rounded-full bg-white/15 px-4 py-2 text-xs font-semibold text-white ring-1 ring-white/25 backdrop-blur transition hover:bg-white hover:text-[#14234b] focus-visible:outline focus-visible:outline-2 focus-visible:outline-[#f2c200] sm:left-8 sm:top-6"
      >
        <ArrowLeft size={14} /> Back to Home
      </a>

      <section className="card-in w-full max-w-3xl overflow-hidden rounded-3xl bg-white shadow-[0_30px_80px_-20px_rgba(0,0,0,0.6)]">
        <div className="h-1.5 bg-gradient-to-r from-[#8f0014] via-[#f2c200] to-[#8f0014]" />

        <div className="px-6 pb-9 pt-8 sm:px-12">
          {/* heading */}
          <div className="flex flex-wrap items-center gap-4">
            <span className="grid h-20 w-20 shrink-0 place-items-center rounded-full bg-white p-1.5 shadow-lg ring-4 ring-[#f2c200]/60">
              <img src={logo} alt="M.C.E. Society’s Abeda Inamdar Senior College crest" className="h-full w-full object-contain" />
            </span>
            <div className="min-w-0 flex-1 leading-tight">
              <p className="text-[11px] font-bold tracking-[0.2em] text-[#8f0014]">M.C.E. SOCIETY’S</p>
              <p className="font-['Playfair_Display',serif] text-lg font-bold text-[#14234b] sm:text-xl">Abeda Inamdar Senior College</p>
              <p className="text-xs text-slate-500">Of Arts, Science and Commerce (Autonomous)</p>
            </div>
          </div>

          <h1 className="mt-7 font-['Playfair_Display',serif] text-2xl font-bold text-[#14234b] sm:text-[32px]">
            Teacher/Academic Staff Portal Login
          </h1>
          <div className="mt-3 h-1 w-16 rounded-full bg-[#f2c200]" />

          {/* form */}
          <form onSubmit={handleSubmit} noValidate className="mt-7">
            {message && (
              <div
                role="alert"
                className={`mb-5 flex items-start gap-2 rounded-lg border px-3.5 py-3 text-sm ${
                  message.type === "error" ? "border-[#8f0014]/20 bg-[#8f0014]/5 text-[#8f0014]" : "border-[#1f9d55]/25 bg-[#e3f3e8] text-[#1f7a46]"
                }`}
              >
                {message.type === "error" ? <AlertCircle size={16} className="mt-0.5 shrink-0" /> : <CheckCircle2 size={16} className="mt-0.5 shrink-0" />}
                {message.text}
              </div>
            )}

            <div className="grid gap-x-8 gap-y-5 sm:grid-cols-2">
              {/* User Type */}
              <div>
                <Label htmlFor="userType">User Type</Label>
                <div className="relative">
                  <select
                    id="userType"
                    value={form.userType}
                    onChange={(e) => set("userType", e.target.value)}
                    aria-invalid={Boolean(errors.userType)}
                    aria-describedby={errors.userType ? "userType-err" : undefined}
                    className={`${input} appearance-none pr-11 ${form.userType ? "text-slate-800" : "text-slate-400"} ${errors.userType ? bad : ok}`}
                  >
                    <option value="" disabled>Select User Type</option>
                    {USER_TYPES.map((t) => (
                      <option key={t} value={t} className="text-slate-800">{t}</option>
                    ))}
                  </select>
                  <ChevronDown size={18} className="pointer-events-none absolute right-4 top-1/2 -translate-y-1/2 text-slate-500" />
                </div>
                <Err id="userType-err" text={errors.userType} />
              </div>

              {/* User ID */}
              <div>
                <Label htmlFor="userId">User ID (Email ID)</Label>
                <input
                  id="userId"
                  type="email"
                  autoComplete="username"
                  value={form.userId}
                  onChange={(e) => set("userId", e.target.value)}
                  aria-invalid={Boolean(errors.userId)}
                  aria-describedby={errors.userId ? "userId-err" : undefined}
                  className={`${input} ${errors.userId ? bad : ok}`}
                />
                <Err id="userId-err" text={errors.userId} />
              </div>

              {/* Password */}
              <div>
                <Label htmlFor="password">Password</Label>
                <div className="relative">
                  <input
                    id="password"
                    type={showPw ? "text" : "password"}
                    autoComplete="current-password"
                    value={form.password}
                    onChange={(e) => set("password", e.target.value)}
                    aria-invalid={Boolean(errors.password)}
                    aria-describedby={errors.password ? "password-err" : undefined}
                    className={`${input} pr-12 ${errors.password ? bad : ok}`}
                  />
                  <button
                    type="button"
                    onClick={() => setShowPw(!showPw)}
                    aria-label={showPw ? "Hide password" : "Show password"}
                    className="absolute right-3 top-1/2 -translate-y-1/2 rounded p-1 text-slate-400 transition hover:text-[#8f0014] focus-visible:outline focus-visible:outline-2 focus-visible:outline-[#8f0014]"
                  >
                    {showPw ? <EyeOff size={18} /> : <Eye size={18} />}
                  </button>
                </div>
                <Err id="password-err" text={errors.password} />
              </div>

              {/* Captcha text */}
              <div>
                <Label htmlFor="captcha">Captcha</Label>
                <input
                  id="captcha"
                  inputMode="numeric"
                  autoComplete="off"
                  placeholder="Captcha (From Image Below)..."
                  value={form.captcha}
                  onChange={(e) => set("captcha", e.target.value)}
                  aria-invalid={Boolean(errors.captcha)}
                  aria-describedby={errors.captcha ? "captcha-err" : undefined}
                  className={`${input} ${errors.captcha ? bad : ok}`}
                />
                <Err id="captcha-err" text={errors.captcha} />
              </div>
            </div>

            {/* captcha image + refresh */}
            <div className="mt-6 flex flex-col items-center">
              <canvas
                ref={canvasRef}
                role="img"
                aria-label="Captcha image. Type the digits you see into the Captcha box."
                className="h-[84px] w-[300px] max-w-full rounded-lg border border-slate-200 shadow-sm"
              />
              <button
                type="button"
                onClick={refreshCaptcha}
                className="group mt-2 inline-flex items-center gap-1.5 rounded px-2 py-1 text-sm font-bold text-[#e0211f] transition hover:text-[#8f0014] focus-visible:outline focus-visible:outline-2 focus-visible:outline-[#8f0014]"
              >
                <RefreshCw size={14} className="transition-transform duration-500 group-hover:rotate-180" /> Refresh Captcha
              </button>
            </div>

            {/* buttons */}
            <div className="mt-5 flex flex-wrap items-center justify-center gap-4">
              <button
                type="submit"
                disabled={loading}
                className="inline-flex h-12 min-w-[12rem] items-center justify-center gap-2 rounded-lg bg-gradient-to-b from-[#a30018] to-[#6d000f] px-8 text-sm font-bold text-white shadow-lg shadow-[#8f0014]/30 transition hover:-translate-y-0.5 hover:brightness-110 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[#8f0014] disabled:cursor-not-allowed disabled:opacity-70 disabled:hover:translate-y-0"
              >
                {loading ? (
                  <>
                    <Loader2 size={18} className="animate-spin motion-reduce:animate-none" /> Signing in…
                  </>
                ) : (
                  "Click to Login"
                )}
              </button>
              <button
                type="button"
                onClick={handleReset}
                disabled={loading}
                className="inline-flex h-12 min-w-[12rem] items-center justify-center rounded-lg border-2 border-[#14234b] bg-white px-8 text-sm font-bold text-[#14234b] transition hover:bg-[#14234b] hover:text-white focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[#14234b] disabled:cursor-not-allowed disabled:opacity-60"
              >
                Click to Reset
              </button>
            </div>
          </form>
        </div>
      </section>
    </main>
  );
}